using namespace std;

int main()
{
    int x = 7;
    if (x > 0)
    {
        cout << "x is positive";
    }
    return 0;
}

using namespace std;

int main()
{
    int x = 7;

    if (x > 0)
    {
        cout << "x is positive";
    }
    else
    {
        cout << "x is not positive";
    }
    return 0;
}

using namespace std;

int main()
{
    int x = 0;

    if (x > 0)
    {
        cout << "x is positive";
    }
    else if (x < 0)
    {
        cout << "x is negative";
    }
    else
    {
        cout << "x is zero";
    }
    return 0;
}

using namespace std;

int main()
{
    int day = 2;

    switch (day)
    {
    case 1:
        cout << "Monday" << endl;
        break;
    case 2:
        cout << "Tuesday" << endl;
        break;
    case 3:
        cout << "Wednesday" << endl;
        break;

    default:
        cout << "Invalid day!" << endl;
    }

    return 0;
}

using namespace std;

int main()
{
    const int x = 10;
    const int y = 5;

    switch (x + y)
    {
    case 15:
        cout << "Result is 15." << endl;
        break;
    case 20:
        cout << "Result is 20." << endl;
        break;
    default:
        cout << "No match found." << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main()
{
    char grade = 'B';

    switch (grade)
    {
    case 'A':
        cout << "Excellent!" << endl;
        break;
    case 'B':
        cout << "Good!" << endl;
        break;
    default:
        cout << "Not specified." << endl;
    }

    return 0;
}

using namespace std;

int main()
{

    int x = 10;
    cout << (x > 0 ? "x is positive" : "x is not positive");
    return 0;
}

using namespace std;

int main()
{

    int x = 0;
    cout << (x > 0 ? "x is positive" : (x < 0 ? "x is not positive" : "x is zero"));
    return 0;
}

